import sympy as sp; x, a = sp.symbols('x a', real=True); f_expr = 2*x - 3*a; integral_expr = x**2 - 3*a*x + 2; f_at_a = f_expr.subs(x, a); a_val = sp.solve(integral_expr.subs(x, a), a); print(f'a values: {a_val}'); a_cand = [av for av in a_val if -3*av > 0]; a_final = a_cand[0] if a_cand else None; print(f'a (f(0)>0): {a_final}'); f_final = f_expr.subs(a, a_final); result = f_final.subs(x, 2); print(f'f(2) = {result}'); integral_check = sp.integrate(f_final, (x, a_final, x)) - integral_expr.subs(a, a_final); integral_simplified = sp.simplify(integral_check); print(f'Integral verification: {integral_simplified}'); print('VERIFY_PASS' if integral_simplified == 0 and result == 7 else 'VERIFY_FAIL')